class Counter {
  #n = 0;
  n = 10;

  bump() {
    this.#n += 1;
    return this.#n;
  }

  static owns(value) {
    return #n in value;
  }
}

const counter = new Counter();
counter.bump();
const copy = { ...counter };

console.log(counter.bump());
console.log(JSON.stringify(copy));
console.log(Counter.owns(copy));
try {
  console.log(counter.bump.call(copy));
} catch (error) {
  console.log(error.name);
}
